function extractJson(value) {
  let text = value;

  if (typeof text === 'object' && text !== null) {
    return text;
  }

  if (!text) {
    throw new Error("Réponse vide de l'agent de configuration");
  }

  text = String(text)
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');

  if (start === -1 || end === -1 || end <= start) {
    throw new Error("Aucun objet JSON complet trouvé dans la réponse : " + text.slice(0, 500));
  }

  const jsonText = text.slice(start, end + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      "JSON invalide généré par l'agent. " +
      error.message +
      "\n\nExtrait autour de l'erreur :\n" +
      jsonText.slice(Math.max(0, error.message.match(/\d+/)?.[0] - 200 || 0), 500)
    );
  }
}

const raw = $json.output ?? $json.text ?? $json.response ?? $json;
let formulaire = extractJson(raw);

if (formulaire.formulaire) {
  formulaire = formulaire.formulaire;
}

return [
  {
    json: {
      formulaire: formulaire
    }
  }
];

const formulaire = $('normaliser formulaire').item.json.formulaire;
const verification = $('vérification formulaire code').item.json;

return [
  {
    json: {
      success: true,
      statut: "formulaire_valide",
      message: "Formulaire généré avec succès",
      formulaire,
      verification
    }
  }
];

const verification = $('vérification formulaire code').item.json;

return [
  {
    json: {
      success: false,
      statut: "a_regenerer",
      message: "Le formulaire doit être régénéré",
      verification,
      erreurs: verification.erreurs || []
    }
  }
];

const input = $input.first().json.body ?? $input.first().json;

const slugsValides = [
  'carburant',
  'transport',
  'batiment',
  'transport_personnel',
  'machines',
  'materiaux',
  'dechets',
  'voyages',
  'employes',
  'production'
];

function normalizeCategory(value) {
  if (!value) return null;

  const v = String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]/g, ' ')
    .trim();

  const map = {
    'carburant': 'carburant',
    'transport': 'transport',
    'transports': 'transport',

    'batiment': 'batiment',
    'batiments': 'batiment',
    'energie': 'batiment',
    'electricite': 'batiment',
    'consommation energie': 'batiment',

    'transport personnel': 'transport_personnel',
    'deplacement employes': 'transport_personnel',
    'deplacements employes': 'transport_personnel',

    'machines': 'machines',
    'machine': 'machines',
    'machines et equipements': 'machines',
    'equipements': 'machines',
    'equipement': 'machines',

    'materiaux': 'materiaux',
    'materiel': 'materiaux',
    'matiere': 'materiaux',
    'matieres': 'materiaux',

    'dechets': 'dechets',
    'dechet': 'dechets',
    'dechets solides': 'dechets',

    'voyages': 'voyages',
    'voyage': 'voyages',
    'voyages professionnels': 'voyages',

    'employes': 'employes',
    'employe': 'employes',
    'personnel': 'employes',

    'production': 'production'
  };

  return map[v] ?? null;
}

const rawSelected =
  input.categories_selectionnees ??
  input.facteurs_selectionnes ??
  [];

let categories = [];

if (Array.isArray(rawSelected)) {
  categories = rawSelected
    .map(item => {
      if (typeof item === 'string') {
        return normalizeCategory(item);
      }

      return normalizeCategory(
        item.categorie ??
        item.category ??
        item.key ??
        item.nom ??
        item.name ??
        item.titre ??
        item.label
      );
    })
    .filter(Boolean);
}

categories = [...new Set(categories)]
  .filter(categorie => slugsValides.includes(categorie));

return [
  {
    json: {
      entreprise_id: input.entreprise_id ?? null,
      formulaire_configuration_id: input.formulaire_configuration_id ?? null,
      entreprise: input.entreprise ?? {},
      categories_selectionnees: categories,
      facteurs_selectionnes: input.facteurs_selectionnes ?? []
    }
  }
];

const selected = $('préparer les données').item.json.categories_selectionnees ?? [];
const formulaireOriginal = $('parser formulaire').item.json.formulaire ?? {};

const titres = {
  carburant: 'Carburant',
  transport: 'Transport',
  batiment: 'Bâtiment et énergie',
  transport_personnel: 'Transport personnel',
  machines: 'Machines et équipements',
  materiaux: 'Matériaux',
  dechets: 'Déchets',
  voyages: 'Voyages professionnels',
  employes: 'Employés',
  production: 'Production'
};

const descriptions = {
  carburant: 'Renseignez les données liées à la consommation de carburant.',
  transport: 'Renseignez les données liées au transport.',
  batiment: 'Renseignez les données liées aux bâtiments et à l’énergie.',
  transport_personnel: 'Renseignez les données liées aux déplacements des employés.',
  machines: 'Renseignez les données liées aux machines et équipements.',
  materiaux: 'Renseignez les données liées aux matériaux.',
  dechets: 'Renseignez les données liées aux déchets.',
  voyages: 'Renseignez les données liées aux voyages professionnels.',
  employes: 'Renseignez les données liées aux employés.',
  production: 'Renseignez les données liées à la production.'
};

function fallbackFields(categorie) {
  const fields = {
    carburant: [
      { nom: 'quantite_consommee', label: 'Quantité consommée', type: 'number', unite: 'tonne', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    transport: [
      { nom: 'distance_parcourue', label: 'Distance parcourue', type: 'number', unite: 'km', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    batiment: [
      { nom: 'consommation_electricite', label: 'Consommation d’électricité', type: 'number', unite: 'kWh', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    transport_personnel: [
      { nom: 'distance_moyenne', label: 'Distance moyenne parcourue', type: 'number', unite: 'km', obligatoire: true, periodes: ['jour', 'semaine', 'mois', 'annee'] }
    ],
    machines: [
      { nom: 'consommation_energie', label: 'Énergie consommée', type: 'number', unite: 'kWh', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    materiaux: [
      { nom: 'quantite_materiau', label: 'Quantité de matériau utilisée', type: 'number', unite: 'tonne', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    dechets: [
      { nom: 'quantite_dechet', label: 'Quantité de déchets', type: 'number', unite: 'tonne', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    voyages: [
      { nom: 'distance_voyage', label: 'Distance du voyage', type: 'number', unite: 'km', obligatoire: true, periodes: ['annee', 'mois'] }
    ],
    employes: [
      { nom: 'nombre_repas', label: 'Nombre de repas', type: 'number', unite: 'repas', obligatoire: false, periodes: ['jour', 'semaine', 'mois', 'annee'] }
    ],
    production: [
      { nom: 'quantite_produite', label: 'Quantité produite', type: 'number', unite: 'tonne', obligatoire: true, periodes: ['annee', 'mois'] }
    ]
  };

  return fields[categorie] ?? [
    { nom: 'valeur', label: 'Valeur', type: 'number', unite: 'unite', obligatoire: true, periodes: ['annee'] }
  ];
}

function normalizeField(champ) {
  let periodes = Array.isArray(champ.periodes) ? champ.periodes : ['annee'];

  periodes = periodes
    .map(p => String(p).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim())
    .map(p => {
      if (p === 'annee' || p === 'an' || p === 'annuel') return 'annee';
      if (p === 'mois') return 'mois';
      if (p === 'semaine') return 'semaine';
      if (p === 'jour') return 'jour';
      return null;
    })
    .filter(Boolean);

  if (periodes.length === 0) {
    periodes = ['annee'];
  }

  return {
    nom: champ.nom ?? champ.name ?? 'valeur',
    label: champ.label ?? 'Valeur',
    type: ['text', 'number', 'select', 'file'].includes(champ.type) ? champ.type : 'number',
    unite: champ.unite ?? champ.unit ?? null,
    obligatoire: champ.obligatoire ?? champ.required ?? true,
    periodes: periodes,
    utilise_pour_calcul: champ.utilise_pour_calcul === true || champ.utilise_pour_calcul === "true",
options: Array.isArray(champ.options) ? champ.options : []
  };
}

const sectionsOriginales = Array.isArray(formulaireOriginal.sections)
  ? formulaireOriginal.sections
  : [];

const sectionsParCategorie = {};

for (const section of sectionsOriginales) {
  const categorie = section.categorie;

  // On garde seulement les catégories cochées dans Laravel
  if (!selected.includes(categorie)) {
    continue;
  }

  const champs = Array.isArray(section.champs)
    ? section.champs.map(normalizeField)
    : [];

  sectionsParCategorie[categorie] = {
    categorie: categorie,
    titre: titres[categorie] ?? section.titre ?? categorie,
    description: descriptions[categorie] ?? section.description ?? '',
    champs: champs.length > 0 ? champs : fallbackFields(categorie)
  };
}

// On reconstruit le formulaire final avec exactement les catégories sélectionnées
const sectionsFinales = selected.map(categorie => {
  return sectionsParCategorie[categorie] ?? {
    categorie: categorie,
    titre: titres[categorie] ?? categorie,
    description: descriptions[categorie] ?? '',
    champs: fallbackFields(categorie)
  };
});

return [
  {
    json: {
      formulaire: {
        statut: 'genere',
        nom_formulaire: formulaireOriginal.nom_formulaire ?? 'Formulaire carbone dynamique',
        sections: sectionsFinales
      }
    }
  }
];

const formulaire = $('normaliser formulaire').item.json.formulaire ?? {};
const prepareData = $('préparer les données').item.json ?? {};

const selected =
  prepareData.categories_selectionnees ??
  prepareData.facteurs_selectionnes ??
  [];

const validSlugs = [
  'carburant',
  'transport',
  'batiment',
  'transport_personnel',
  'machines',
  'materiaux',
  'dechets',
  'voyages',
  'employes',
  'production'
];

const erreurs = [];

const sections = Array.isArray(formulaire.sections) ? formulaire.sections : [];

if (!Array.isArray(formulaire.sections)) {
  erreurs.push("Le formulaire ne contient pas un tableau sections.");
}

const categoriesGenerees = sections.map(section => section.categorie);

if (sections.length !== selected.length) {
  erreurs.push(`Nombre de sections incorrect : attendu ${selected.length}, reçu ${sections.length}.`);
}

for (const categorie of selected) {
  if (!categoriesGenerees.includes(categorie)) {
    erreurs.push(`Catégorie manquante : ${categorie}`);
  }
}

for (const categorie of categoriesGenerees) {
  if (!validSlugs.includes(categorie)) {
    erreurs.push(`Catégorie invalide : ${categorie}`);
  }

  if (!selected.includes(categorie)) {
    erreurs.push(`Catégorie non sélectionnée présente : ${categorie}`);
  }
}

const duplicates = categoriesGenerees.filter((item, index) => categoriesGenerees.indexOf(item) !== index);

for (const duplicate of [...new Set(duplicates)]) {
  erreurs.push(`Doublon de catégorie : ${duplicate}`);
}

for (const section of sections) {
  if (!section.categorie) {
    erreurs.push("Une section ne contient pas de catégorie.");
  }

  if (!section.titre) {
    erreurs.push(`La section ${section.categorie ?? 'inconnue'} ne contient pas de titre.`);
  }

  if (!Array.isArray(section.champs) || section.champs.length === 0) {
    erreurs.push(`La section ${section.categorie} ne contient aucun champ.`);
    continue;
  }

  const champsCalcul = section.champs.filter(champ =>
    champ.utilise_pour_calcul === true || champ.utilise_pour_calcul === "true"
  );

  if (champsCalcul.length !== 1) {
    erreurs.push(`La section ${section.categorie} doit contenir exactement un champ utilise_pour_calcul=true.`);
  }

  for (const champ of section.champs) {
    if (!champ.nom) erreurs.push(`Champ sans nom dans ${section.categorie}`);
    if (!champ.label) erreurs.push(`Champ sans label dans ${section.categorie}`);
    if (!champ.type) erreurs.push(`Champ sans type dans ${section.categorie}`);

    if (!Object.prototype.hasOwnProperty.call(champ, 'unite')) {
      erreurs.push(`Champ sans unité dans ${section.categorie}`);
    }

    if (!Object.prototype.hasOwnProperty.call(champ, 'obligatoire')) {
      erreurs.push(`Champ sans obligatoire dans ${section.categorie}`);
    }

    if (!Object.prototype.hasOwnProperty.call(champ, 'utilise_pour_calcul')) {
      erreurs.push(`Champ sans utilise_pour_calcul dans ${section.categorie}`);
    }

    if (!['text', 'number', 'select', 'file'].includes(champ.type)) {
      erreurs.push(`Type invalide dans ${section.categorie} : ${champ.type}`);
    }

    if (!Array.isArray(champ.periodes)) {
      erreurs.push(`Périodes invalides dans le champ ${champ.nom}`);
    } else {
      for (const periode of champ.periodes) {
        if (!['jour', 'semaine', 'mois', 'annee'].includes(periode)) {
          erreurs.push(`Période invalide dans ${champ.nom} : ${periode}`);
        }
      }
    }

    if (champ.type === 'select') {
      if (!Array.isArray(champ.options) || champ.options.length < 2) {
        erreurs.push(`Le champ select ${champ.nom} doit contenir au moins deux options.`);
      }
    }

    const isCalculationField =
      champ.utilise_pour_calcul === true ||
      champ.utilise_pour_calcul === "true";

    if (isCalculationField && champ.type !== 'number') {
      erreurs.push(`Le champ de calcul ${champ.nom} doit être de type number.`);
    }
  }
}

return [
  {
    json: {
      valide: erreurs.length === 0,
      statut: erreurs.length === 0 ? "valide" : "a_regenerer",
      erreurs,
      message: erreurs.length === 0 ? "Formulaire valide" : "Formulaire invalide"
    }
  }
];
